/* eslint-disable max-len */

'use strict';

// MODULES //

var radf2 = require( './radf2.js' );
var radf3 = require( './radf3.js' );
var radf4 = require( './radf4.js' );
var radf5 = require( './radf5.js' );
var radfg = require( './radfg.js' );


// MAIN //

/**
* Performs the forward real-valued Fast Fourier Transform.
*
* @private
* @param {number} n - length of the sequence to transform
* @param {Float64Array} c - input array containing sequence to be transformed
* @param {Float64Array} ch - working array for intermediate results
* @param {Float64Array} wa - array of twiddle factors
* @param {Int32Array} ifac - array containing factorization information
* @returns {void}
*/
function rfftf1( n, c, ch, wa, ifac ) {
	var idl1;
	var ido;
	var ix4;
	var ix3;
	var ix2;
	var nf;
	var na;
	var l2;
	var l1;
	var kh;
	var iw;
	var ip;
	var k1;
	var i;

	// Function Body:
	nf = ifac[ 1 ];
	na = 1;
	l2 = n;
	iw = n - 1;
	for ( k1 = 1; k1 <= nf; k1++ ) {
		kh = nf - k1;
		ip = ifac[ kh + 2 ];
		l1 = l2 / ip;
		ido = n / l2;
		idl1 = ido * l1;
		iw -= ( ip - 1 ) * ido;
		na = 1 - na;
		switch ( ip ) {
		case 4:
			ix2 = iw + ido;
			ix3 = ix2 + ido;
			radf4( ido, l1, ( na ) ? ch : c, ( na ) ? c : ch, wa[ iw ], wa[ ix2 ], wa[ ix3 ] );
			break;
		case 2:
			radf2( ido, l1, ( na ) ? ch : c, ( na ) ? c : ch, wa[ iw ], wa[ ix2 ] );
			break;
		case 3:
			ix2 = iw + ido;
			radf3( ido, l1, ( na ) ? ch : c, ( na ) ? c : ch, wa[ iw ], wa[ ix2 ] );
			break;
		case 5:
			ix2 = iw + ido;
			ix3 = ix2 + ido;
			ix4 = ix3 + ido;
			radf5( ido, l1, ( na ) ? ch : c, ( na ) ? c : ch, wa[ iw ], wa[ ix2 ], wa[ ix3 ], wa[ ix4 ] );
			break;
		default:
			if ( ido === 1 ) {
				na = 1 - na;
			}
			if ( na === 0 ) {
				radfg( ido, ip, l1, idl1, c, c, c, ch, ch, c, wa[ iw ] );
				na = 1;
			} else {
				radfg( ido, ip, l1, idl1, ch, ch, ch, c, c, wa[ iw ] );
				na = 0;
			}
			break;
		}
		l2 = l1;
	}
	if ( na === 1 ) {
		return;
	}
	for ( i = 0; i < n; i++ ) {
		c[ i ] = ch[ i ];
	}
}


// EXPORTS //

module.exports = rfftf1;
